import test from'node:test';import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{arrivalProbeProgram}from'./arrival-source.mjs';import{readFileSync}from'node:fs';
test('actual generated remote read-only probe parses and splits deployment fields by newline',()=>{const code=arrivalProbeProgram({installId:'00000000-0000-4000-8000-000000000001'});execFileSync(process.execPath,['--input-type=module','--check'],{input:code});const expression=code.match(/const state=(.*?);const runtime=/)?.[1];assert(expression);const state=Function('fs','return '+expression)({readFileSync:()=>['ref=fictional-ref','result=ok','other=a=b'].join(String.fromCharCode(10))});assert.deepEqual(state,{ref:'fictional-ref',result:'ok',other:'a=b'});assert(!/writeFile|unlink|chmod|utimes|systemctl.*restart/.test(code));});
test('slow actual status precedes fresh source receipt; 60s proof validation is retained',()=>{const source=readFileSync(new URL('./operator-release.mjs',import.meta.url),'utf8');const a=source.indexOf("const installed=JSON.parse(ssh(stagingInstallerCommand('status'"),b=source.indexOf('const checksum=readChecksum();'),c=source.indexOf('const checksumCheckedAt=new Date().toISOString();');assert(a>=0&&a<b&&b<c);assert(source.includes('{timeout:180000}'));assert(source.includes('createCleanupRequest(grant,{output:checksum,checkedAt:checksumCheckedAt,arrival:initialArrival})'));});
